mapper.select:
SELECT t.id, t.task_no, COALESCE(NULLIF(LEFT(TRIM(first_turn.user_message), 64), ''), NULLIF(s.title, ''), '智能导诊与预约') AS title, t.status, t.updated_at FROM agent_task t JOIN agent_session s ON s.id = t.session_id AND s.patient_id = t.patient_id LEFT JOIN agent_turn first_turn ON first_turn.task_id = t.id AND first_turn.turn_no = 1 WHERE t.patient_id = #{patientId} AND t.task_type = 'APPOINTMENT_BOOKING'
AND t.id < #{before}
ORDER BY t.id DESC LIMIT #{limit}
